// undone, in the page (the browser's confirm would freeze it): await
// ask("Delete it?").
import { useEffect, useState } from "react"
import { Button } from "@/components/ui/button.tsx"
import { Card } from "@/components/ui/card.tsx"
import { t } from "./i18n.ts"

type Question = { text: string; answer: (yes: boolean) => void }
let show: ((q: Question) => void) | undefined

/** Asks a yes or no question; true on yes. */
export function ask(text: string): Promise<boolean> {
  return new Promise((answer) => {
    if (!show) return answer(false)
    show({ text, answer })
  })
}

/** Where the questions appear: once, in the layout. */
export function Confirmer() {
  const [question, setQuestion] = useState<Question | null>(null)
  useEffect(() => {
    show = setQuestion
    return () => {
      show = undefined
    }
  }, [])
  if (!question) return null
  const answer = (yes: boolean) => {
    setQuestion(null)
    question.answer(yes)
  }
  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4"
      role="dialog"
      aria-modal="true"
      onKeyDown={(e) => e.key === "Escape" && answer(false)}
    >
      <Card className="w-full max-w-sm">
        <p className="mb-4">{question.text}</p>
        <div className="flex justify-end gap-2">
          <Button variant="outline" onClick={() => answer(false)}>
            {t("cancel")}
          </Button>
          <Button autoFocus onClick={() => answer(true)}>
            {t("yes")}
          </Button>
        </div>
      </Card>
    </div>
  )
}
